import { models as catalogModels } from "./models";
import type { ModelSummary } from "./models";

export interface ModelsState {
  /** The models to display. */
  models: ModelSummary[];
}

// Assembles the Models section's data from the published catalog dataset
// (`models.json`, regenerated by `tcab catalog` from the models/ folder). The
// catalog is fully static and bundled into every host, so this is a plain
// selector; an unpopulated dataset simply renders the empty state.
export function useModels(): ModelsState {
  return { models: catalogModels };
}
